from config_reader import read_settings

class TestReadSettings(unittest.TestCase):

    def test_basic_valid_config(self):
        text = "endpoint=http://api.test.com\nenabled=true"
        expected = {'endpoint': 'http://api.test.com', 'enabled': True}
        self.assertEqual(read_settings(text), expected)

    def test_basic_valid_config_false(self):
        text = "endpoint=http://api.test.com\nenabled=false"
        expected = {'endpoint': 'http://api.test.com', 'enabled': False}
        self.assertEqual(read_settings(text), expected)

    def test_whitespace_handling(self):
        text = "  endpoint =  http://api.test.com  \n\nenabled=true  \n"
        expected = {'endpoint': 'http://api.test.com', 'enabled': True}
        self.assertEqual(read_settings(text), expected)

    def test_comments_and_blank_lines(self):
        text = """
        # This is a comment
        endpoint=http://api.test.com

        enabled=true
        # Another comment
        """
        expected = {'endpoint': 'http://api.test.com', 'enabled': True}
        self.assertEqual(read_settings(text), expected)

    def test_missing_endpoint(self):
        text = "enabled=true"
        with self.assertRaisesRegex(ValueError, "Missing required key: endpoint"):
            read_settings(text)

    def test_missing_enabled(self):
        text = "endpoint=http://api.test.com"
        with self.assertRaisesRegex(ValueError, "Missing required key: enabled"):
            read_settings(text)

    def test_duplicate_key(self):
        text = "endpoint=url1\nendpoint=url2"
        with self.assertRaisesRegex(ValueError, "Duplicate key found: endpoint"):
            read_settings(text)

    def test_malformed_line_no_equals(self):
        text = "endpoint=url\njust_a_line"
        with self.assertRaisesRegex(ValueError, "Malformed line: must contain '='"):
            read_settings(text)

    def test_invalid_enabled_value(self):
        text = "endpoint=url\nenabled=maybe"
        with self.assertRaisesRegex(ValueError, "Invalid value for enabled: must be 'true' or 'false'"):
            read_settings(text)

    def test_extra_keys_allowed(self):
        # Testing that extra keys are allowed as per typical config file behavior, 
        # since the requirement only specifies missing/duplicate/malformed/unknown (ambiguous)
        text = "endpoint=url\nenabled=true\nversion=1.0"
        expected = {'endpoint': 'url', 'enabled': True, 'version': '1.0'}
        self.assertEqual(read_settings(text), expected)

    def test_empty_input(self):
        text = ""
        with self.assertRaisesRegex(ValueError, "Missing required key: endpoint"):
            read_settings(text)

    def test_only_comments_and_blanks(self):
        text = "\n#comment\n   \n"
        with self.assertRaisesRegex(ValueError, "Missing required key: endpoint"):
            read_settings(text)

