        text = "endpoint=http://api.test.com\nenabled="
        expected = {'endpoint': 'http://api.test.com', 'enabled': False}
        self.assertEqual(read_settings(text), expected)

    def test_value_is_just_whitespace(self):
        text = "endpoint= \nenabled= true"
